param([switch]$ExecutionAuthorized)
# One ReleaseCPU reader compile/link using retained objects and archived headers, never a project build or program run.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$src=Join-Path $repo 'src';$logs=Join-Path $tests 'logs';$tag='upl_damp_mid_partial_reader_ReleaseCPU_r1';$cache=@{}
$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.helper.json');$cpp=Join-Path $PSScriptRoot 'upl_damp_mid_partial_r1.cpp';$neutral=Join-Path $PSScriptRoot 'upl_cpu_public_native_r1.cpp';$obj=Join-Path $folder 'helper.obj';$exe=Join-Path $folder 'upl_damp_mid_partial_r1.exe';$deps=Join-Path $folder 'compile.dependencies.json'
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function RawE([string]$p){$f=Get-Item -LiteralPath ([IO.Path]::GetFullPath($p)) -Force;Need (!$f.PSIsContainer) 'Expected a file';return [ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
function E([string]$p){$key=([IO.Path]::GetFullPath($p)).ToLowerInvariant();if(!$cache.ContainsKey($key)){$cache[$key]=RawE $p};return $cache[$key]}
function V($rows){foreach($e in @($rows)){Need ($e.path -and $null -ne $e.bytes -and $e.sha256 -match '^[0-9a-fA-F]{64}$') 'Malformed Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed/conflicting Entry: '+$e.path)}}
function FinalV($rows){$seen=@{};foreach($e in @($rows)){$key=([IO.Path]::GetFullPath($e.path)).ToLowerInvariant();if(!$seen.ContainsKey($key)){$seen[$key]=RawE $e.path};$a=$seen[$key];Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed/conflicting final Entry: '+$e.path)}}
function J([string]$p){return ([IO.File]::ReadAllText($p)|ConvertFrom-Json)}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function PassedCall($e){V @($e);$c=J $e.path;Need ($c.direct_native_call -and $c.typed_LASTEXITCODE_captured_immediately -and $c.owned_call_exited -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure) 'Actual direct typed tool exit0 required';return $c}
function Owned($tool,[string[]]$argv,[string]$suffix){
  $p=Join-Path $logs ($tag+'_'+$suffix+'.call.json');$log=Join-Path $logs ($tag+'_'+$suffix+'.log');Fresh @($p,$log);V @($tool);[IO.File]::WriteAllBytes($log,[byte[]]@());$code=$null;$failure=$null;$started=[DateTime]::UtcNow.ToString('o');$prior=$ErrorActionPreference;Push-Location $src
  try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$prior}
  Save $p ([ordered]@{program=$tool;arguments=$argv;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);build_tool_only=$true;program_run=$false;physical_acceptance=$false});return (E $p)
}
Need $ExecutionAuthorized.IsPresent 'Root full read and explicit compile/link authorization required';Fresh @($folder,$record)
foreach($suffix in @('Compile','Link')){Fresh @((Join-Path $logs ($tag+'_'+$suffix+'.call.json')),(Join-Path $logs ($tag+'_'+$suffix+'.log')))}
$buildE=E (Join-Path $logs 'upl_damp_ReleaseCPU_r2.build.json');$b=J $buildE.path;$recipeE=E (Join-Path $logs 'upl_damp_long_reader_ReleaseCPU_r1.helper.json');$h=J $recipeE.path
Need ($b.passed -and $b.stage -ceq 'upl_damp_build_r2' -and $b.configuration -ceq 'ReleaseCPU' -and $b.source_bindings_unchanged -and $b.exact_object_basename_closure -and $b.objects_include_project_main -and @($b.objects).Count -eq 86 -and @($b.source_snapshot).Count -eq 265 -and @($b.runtime).Count -eq 4) 'Sealed retained ReleaseCPU86/source265 build required'
[void](PassedCall $b.project_call);Need ($h.passed -and $h.stage -ceq 'upl_damp_long_reader_build_r1' -and $h.kind -ceq 'reader' -and $h.configuration -ceq 'ReleaseCPU' -and $h.source_build.sha256 -ceq $buildE.sha256 -and $h.exact_link_closure_verified -and @($h.objects).Count -eq 85 -and $h.link_object_count -eq 86 -and @($h.libraries).Count -eq 17) 'Actual accepted long reader85+1 recipe required'
$cc=PassedCall $h.compile_call;$lc=PassedCall $h.link_call;Need ([IO.Path]::GetFileName($cc.program.path) -ieq 'cl.exe' -and [IO.Path]::GetFileName($lc.program.path) -ieq 'link.exe' -and $cc.working_directory -ieq $src -and $lc.working_directory -ieq $src) 'Actual MSVC cl/link vectors required'
$snapshots=@();$headerMap=@{};$snapshotRoot=$null
foreach($p in $b.source_snapshot){Need ($p.original.bytes -eq $p.snapshot.bytes -and $p.original.sha256 -ieq $p.snapshot.sha256 -and [IO.Path]::GetFileName($p.original.path) -ieq [IO.Path]::GetFileName($p.snapshot.path)) 'Recorded source original/snapshot identity differed as of build';$parent=Split-Path -Parent $p.snapshot.path;if(!$snapshotRoot){$snapshotRoot=$parent};Need ($parent -ieq $snapshotRoot -and !$headerMap.ContainsKey($p.snapshot.path.ToLowerInvariant())) 'Snapshot root/membership differs';$snapshots+=@($p.snapshot);$headerMap[$p.snapshot.path.ToLowerInvariant()]=$p.snapshot}
foreach($p in @($b.documentation_snapshot,$b.case_readme_snapshot)){Need ($p.original.bytes -eq $p.snapshot.bytes -and $p.original.sha256 -ieq $p.snapshot.sha256) 'Recorded doc/README pair differed as of build'}
$names=@(Get-ChildItem -LiteralPath $snapshotRoot -File|Where-Object{$_.Extension -in @('.cpp','.h','.cu','.cuh')}|ForEach-Object{$_.FullName});Need ($names.Count -eq 265 -and !(Compare-Object ($names|Sort-Object) ($snapshots.path|Sort-Object))) 'Archived265 code membership differs'
$authors=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_mid_partial_r1.json')),(E (Join-Path $tests 'notes\upl_damp_mid_r1.json')),(E $cpp),(E $neutral),(E (Join-Path $tests 'notes\upl_cpu_public_native_r1.json')));Need ((E $neutral).sha256 -ceq '9f6668bfe3d1bbcca7c45c58809f7062c21fcb46baae76f0a2a1b0ef3ca56d38') 'Immutable neutral source changed'
$objects=@($b.objects|Where-Object{[IO.Path]::GetFileName($_.path) -ine 'main.obj'});$byName=@{};foreach($e in $objects){$key=[IO.Path]::GetFileName($e.path).ToLowerInvariant();Need (!$byName.ContainsKey($key)) 'Duplicate retained object basename';$byName[$key]=$e};Need ($objects.Count -eq 85 -and $byName.Count -eq 85) 'Exact85 retained non-main objects required'
$selected=[ordered]@{};Need ($h.environment.exit_code -eq 0) 'Retained selected environment failed';foreach($key in @('INCLUDE','LIB','VCToolsInstallDir','WindowsSdkDir','WindowsSDKVersion')){$value=[string]$h.environment.selected.$key;Need (![string]::IsNullOrWhiteSpace($value)) ('Missing environment '+$key);$selected[$key]=$value}
$bindings=@($buildE,$b.project_call,$b.program,$b.log,$b.binlog,$recipeE,$h.compile_call,$h.link_call,$h.environment_source,$h.compiler_dependency_record,$cc.program,$cc.log,$lc.program,$lc.log,$b.documentation_snapshot.snapshot,$b.case_readme_snapshot.snapshot)+$authors+$snapshots+@($b.objects)+@($h.author_files)+@($h.tools)+@($h.environment.tools)+@($h.libraries)
foreach($p in $b.runtime){Need ($p.original.bytes -eq $p.copy.bytes -and $p.original.sha256 -ieq $p.copy.sha256) 'Recorded runtime copy differed as of build';$bindings+=@($p.copy)} # Hash copies only, not canonical originals.
$oldCpp=Join-Path $PSScriptRoot 'upl_damp_long_native_r1.cpp';$liveInclude='/I'+(Join-Path $src 'source');$compile=@();$cs=0;$fo=0;$fd=0;$de=0;$inc=0
foreach($a in $cc.arguments){if($a -ieq $oldCpp){$compile+=$cpp;$cs++}elseif($a -ieq $liveInclude){$compile+='/I'+$snapshotRoot;$inc++}elseif($a.StartsWith('/Fo',[StringComparison]::OrdinalIgnoreCase)){$compile+='/Fo'+$obj;$fo++}elseif($a.StartsWith('/Fd',[StringComparison]::OrdinalIgnoreCase)){$compile+='/Fd'+(Join-Path $folder 'compile.pdb');$fd++}elseif($a -ieq $h.compiler_dependency_record.path){$compile+=$deps;$de++}else{$compile+=$a}}
Need ($cs -eq 1 -and $fo -eq 1 -and $fd -eq 1 -and $de -eq 1 -and $inc -eq 1 -and $compile -ccontains '/sourceDependencies' -and $compile -ccontains '/MT' -and $compile -ccontains '/fp:precise' -and $compile -ccontains '/std:c++17') 'Only CPP/Fo/Fd/deps and one archived-header include remap permitted'
$link=@();$maps=@();$hh=0;$oo=0;foreach($a in $lc.arguments){if($a -ieq $h.helper_object.path){$link+=$obj;$hh++}elseif($a.StartsWith('/OUT:',[StringComparison]::OrdinalIgnoreCase)){$link+='/OUT:'+$exe;$oo++}elseif($a.EndsWith('.obj',[StringComparison]::OrdinalIgnoreCase)){$name=[IO.Path]::GetFileName($a).ToLowerInvariant();Need ($byName.ContainsKey($name)) 'Unknown retained object';$link+=$byName[$name].path;$maps+=@{old_recipe_object=$a;retained=$byName[$name]}}else{$link+=$a}}
$linked=@($link|Where-Object{$_.EndsWith('.obj',[StringComparison]::OrdinalIgnoreCase)});$libs=@($link|Where-Object{$_.EndsWith('.lib',[StringComparison]::OrdinalIgnoreCase)});$libraryNames=@($h.libraries|ForEach-Object{[IO.Path]::GetFileName($_.path)});Need ($hh -eq 1 -and $oo -eq 1 -and $maps.Count -eq 85 -and $linked.Count -eq 86 -and @($linked|Sort-Object -Unique).Count -eq 86 -and !(Compare-Object ($linked|Sort-Object) ((@($objects.path)+@($obj))|Sort-Object)) -and $libs.Count -eq 17 -and ($libs -join [char]0) -ieq ($libraryNames -join [char]0) -and @($link|Where-Object{$_.StartsWith('/PDB:',[StringComparison]::OrdinalIgnoreCase)}).Count -eq 0) 'Exact85+1 link/ordered17 library closure required'
V $bindings;foreach($key in $selected.Keys){[Environment]::SetEnvironmentVariable($key,[string]$selected[$key],'Process')};$env:PATH=[IO.Path]::GetDirectoryName($cc.program.path)+';'+$env:PATH
[void](New-Item -ItemType Directory -Path $folder);$compileCall=$null;$linkCall=$null;$program=$null;$helperObject=$null;$dependency=$null;$projectHeaders=@();$runtime=@();$failure=$null
try{
  $compileCall=Owned $cc.program $compile 'Compile';[void](PassedCall $compileCall);$helperObject=E $obj;$dependency=E $deps;$dep=J $deps
  $local=@($dep.Data.Includes|Where-Object{$_.StartsWith($PSScriptRoot+'\',[StringComparison]::OrdinalIgnoreCase)});Need ($dep.Data.Source -ieq $cpp -and $local.Count -eq 1 -and $local[0] -ieq $neutral) 'Actual compiler source/single neutral include differs'
  foreach($path in $dep.Data.Includes){Need (!$path.StartsWith((Join-Path $src 'source')+'\',[StringComparison]::OrdinalIgnoreCase)) 'Compiler used a mutable live project header';if($path.StartsWith($snapshotRoot+'\',[StringComparison]::OrdinalIgnoreCase)){Need ($headerMap.ContainsKey($path.ToLowerInvariant())) 'Compiler header outside archived265';$projectHeaders+=@($headerMap[$path.ToLowerInvariant()])}};Need ($projectHeaders.Count -gt 0) 'Actual archived project dependencies missing';V $projectHeaders
  $linkCall=Owned $lc.program $link 'Link';[void](PassedCall $linkCall);$program=E $exe
  foreach($p in $b.runtime){$to=Join-Path $folder ([IO.Path]::GetFileName($p.copy.path));Fresh @($to);Copy-Item -LiteralPath $p.copy.path -Destination $to;$copy=E $to;Need ($copy.bytes -eq $p.copy.bytes -and $copy.sha256 -ieq $p.copy.sha256) 'Own reader runtime copy differs';$runtime+=@{original=$p.copy;copy=$copy}}
}catch{$failure=$_.Exception.Message}
$unchanged=$false;try{$post=$bindings+@($projectHeaders);foreach($e in @($helperObject,$dependency,$program,$compileCall,$linkCall)){if($e){$post+=@($e)}};foreach($p in $runtime){$post+=@($p.original,$p.copy)};FinalV $post;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
$passed=(!$failure -and $unchanged -and $null -ne $program -and $runtime.Count -eq 4)
Save $record ([ordered]@{stage='upl_damp_mid_partial_reader_build_r1';passed=[bool]$passed;status=$(if($passed){'frozen_damp_mid_partial_CPU_reader_linked_not_run'}else{'damp_mid_reader_build_failed_retained'});kind='reader';configuration='ReleaseCPU';source_build=$buildE;source_snapshots265=$snapshots;documentation_snapshot=$b.documentation_snapshot.snapshot;case_readme_snapshot=$b.case_readme_snapshot.snapshot;recorded_original_snapshot_identity_checked=$true;archived_header_include_root=$snapshotRoot;project_header_include_remaps=1;actual_project_headers=$projectHeaders;actual_headers_archived_not_live=$true;retained_compiler_recipe=$recipeE;environment_source=$h.environment_source;environment=@{selected=$selected;tools=$h.environment.tools;exit_code=$h.environment.exit_code};tools=@($cc.program,$lc.program);libraries=$h.libraries;author_files=$authors;neutral_include=(E $neutral);objects=$objects;CPU_non_main_objects=85;object_mappings=$maps;helper_object=$helperObject;link_object_count=86;exact_link_closure_verified=$true;compile_call=$compileCall;link_call=$linkCall;compiler_dependency_record=$dependency;runtime=$runtime;program=$program;inputs=$bindings;failure=$failure;frozen_build_program_inputs_runtime_unchanged=$unchanged;live_production_sources_frozen_by_this_run=$false;canonical_programs_rechecked=$false;historical_original_runtime_rechecked=$false;independent_final_rehash_performed=$unchanged;production_build_executed=$false;program_run=$false;solver_started=$false;canonical_program_installed=$false;physical_acceptance=$false})
if(!$passed){throw "Mid reader build failed; preserve $record/partials"};Write-Output "Mid pure reader linked, not run: $record"
